      let core = &url[..cut];
      let Some(i) = core.find("://") else { return -1 };
      let rest = &core[i + 3..];
      let auth = &rest[..rest.find('/').unwrap_or(rest.len())];
      let hostport = match auth.find('@') { Some(a) => &auth[a + 1..], None => auth };
      let Some(c) = hostport.find(':') else { return -1 };
      parse_port(&hostport[c + 1..])
  }
  fn parse_port(port_str: &str) -> i32 {               // -1 == sentinel
